er_id":"bf96f318-5035-484a-98a0-a324d05b84fa","model_id":null,"vehicle_version_id":null,"create_product":false,"create_manufacturer":false,"create_model":true,"create_version":true,"product_exists":true},"result":"ok"},{"line_number":689,"errors":[],"warnings":[],"payload":{"action":"new","period_action":"create","applyable":true,"sku":"TDI2400","name":"TERMINAL DE DIRE├ç├âO","montadora":"JEEP","modelo":"COMPASS","versao":"","year_start":2017,"year_end":null,"product_id":"15e4c3c7-14d6-4d70-bc08-a034cb6d756d","manufacturer_id":"bf96f318-5035-484a-98a0-a324d05b84fa","model_id":null,"vehicle_version_id":null,"create_product":false,"create_manufacturer":false,"create_model":true,"create_version":true,"product_exists":true},"result":"ok"},{"line_number":690,"errors":[],"warnings":[],"payload":{"action":"new","period_action":"create","applyable":true,"sku":"TDI2401","name":"TERMINAL DE DIRE├ç├âO","montadora":"FIAT","modelo":"TORO","versao":"","year_start":2016,"year_end":null,"product_id":"5750c156-30ee-4942-9104-bc59c8fd69b0","manufacturer_id":"33333333-3333-3333-3333-333333333001","model_id":null,"vehicle_version_id":null,"create_product":false,"create_manufacturer":false,"create_model":true,"create_version":true,"product_exists":true},"result":"ok"},{"line_number":691,"errors":[],"warnings":[],"payload":{"action":"new","period_action":"create","applyable":true,"sku":"TDI2401","name":"TERMINAL DE DIRE├ç├âO","montadora":"JEEP","modelo":"RENEGADE","versao":"","year_start":2015,"year_end":null,"product_id":"5750c156-30ee-4942-9104-bc59c8fd69b0","manufacturer_id":"bf96f318-5035-484a-98a0-a324d05b84fa","model_id":null,"vehicle_version_id":null,"create_product":false,"create_manufacturer":false,"create_model":true,"create_version":true,"product_exists":true},"result":"ok"},{"line_number":692,"errors":[],"warnings":[],"payload":{"action":"new","period_action":"create","applyable":true,"sku":"TDI2401","name":"TERMINAL DE DIRE├ç├âO","montadora":"JEEP","modelo":"COMPASS","versao":"","year_start":2017,"year_end":null,"product_id":"5750c156-30ee-4942-9104-bc59c8fd69b0","manufacturer_id":"bf96f318-5035-484a-98a0-a324d05b84fa","model_id":null,"vehicle_version_id":null,"create_product":false,"create_manufacturer":false,"create_model":true,"create_version":true,"product_exists":true},"result":"ok"}]'::jsonb)
  loop
    insert into public.import_items (
      import_id, line_number, errors, warnings, payload, result
    ) values (
      v_import_id,
      (v_item ->> 'line_number')::int,
      coalesce(
        (select array_agg(x) from jsonb_array_elements_text(coalesce(v_item -> 'errors', '[]'::jsonb)) as t(x)),
        '{}'::text[]
      ),
      coalesce(
        (select array_agg(x) from jsonb_array_elements_text(coalesce(v_item -> 'warnings', '[]'::jsonb)) as t(x)),
        '{}'::text[]
      ),
      v_item -> 'payload',
      coalesce(v_item ->> 'result', 'ok')
    );
  end loop;

  v_result := public.apply_catalog_applications_import(v_import_id);

  select count(*)::int into v_pvc_after from public.product_vehicle_compatibility;
  select count(*)::int into v_vv_after from public.vehicle_versions where status = 'active';

  update public.imports
  set report = coalesce(report, '{}'::jsonb) || jsonb_build_object(
    'm4_evidence',
    jsonb_build_object(
      'pvc_before', v_pvc_before,
      'pvc_after', v_pvc_after,
      'pvc_delta', v_pvc_after - v_pvc_before,
      'vv_before', v_vv_before,
      'vv_after', v_vv_after,
      'vv_delta', v_vv_after - v_vv_before,
      'apply_result', v_result,
      'policy', 'stage all; RPC skips review/error'
    )
  )
  where id = v_import_id;
end;
$m4$;

select
  id as import_id,
  status,
  report -> 'm4_evidence' as m4_evidence,
  report -> 'total' as staged_total,
  report -> 'applyable' as staged_applyable
from public.imports
where filename = 'FIND004-M4 LISTA SUSP. aplicação FAL.csv'
order by created_at desc
limit 1;
